function Assert-ProductArtifact([string]$Path,[string]$Target,[string]$ModId,[string]$Version) {
    # Exact filename selection is necessary but not sufficient: a renamed stale JAR
    # must not pass. Check the Loader metadata generated by the actual Target build.
    $archive=[IO.Compression.ZipFile]::OpenRead($Path)
    try {
        $metadata=if($Target.EndsWith('-fabric')){'fabric.mod.json'}elseif($Target.EndsWith('-forge')){'META-INF/mods.toml'}else{'META-INF/neoforge.mods.toml'}
        $entry=$archive.GetEntry($metadata)
        if($null-eq$entry-or$entry.Length-le0-or$entry.Length-gt262144){throw "$Target artifact metadata missing or oversized"}
        $reader=[IO.StreamReader]::new($entry.Open())
        try{$text=$reader.ReadToEnd()}finally{$reader.Dispose()}
        if($Target.EndsWith('-fabric')){
            $mod=$text|ConvertFrom-Json
            $valid=$mod.id-ceq$ModId-and$mod.version-ceq$Version
        }else{
            $valid=$false
            foreach($block in [regex]::Matches($text,'(?ms)^\s*\[\[mods\]\]\s*(.*?)(?=^\s*\[|\z)')){
                $id=[regex]::Match($block.Groups[1].Value,'(?m)^\s*modId\s*=\s*["'']([^"'']+)["'']')
                $versionValue=[regex]::Match($block.Groups[1].Value,'(?m)^\s*version\s*=\s*["'']([^"'']+)["'']')
                if($id.Groups[1].Value-ceq$ModId-and$versionValue.Groups[1].Value-ceq$Version){$valid=$true}
            }
        }
        if(-not$valid){throw "$Target artifact metadata identity/version mismatch"}
    }finally{$archive.Dispose()}
}
